import {campaignFinanceIndex as catalog} from './campaign-finance-index.js';
import {campaignRoster} from './campaigns-2026.js';
import {groupReportedNames,financeCSV} from './campaign-finance.js';

const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dollars=cents=>cents===null?'Not reported':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
const unitById=new Map(catalog.units.map(r=>[r.id,r]));
const reportById=new Map(catalog.reports.map(r=>[r.id,r]));
const sourceById=new Map(catalog.sources.map(r=>[r.id,r]));
const unitsFor=id=>catalog.units.filter(r=>r.id===id||r.candidateIds.includes(id)).sort((a,b)=>Number(b.designation==='P')-Number(a.designation==='P'));
const sum=(reports,key)=>reports.some(r=>r.metrics[key]!==null&&r.metrics[key]!==undefined)?reports.reduce((n,r)=>n+(r.metrics[key]||0),0):null;
const receipts=r=>r.metrics.receipts??(r.metrics.contributions===null&&r.metrics.otherReceipts===null?null:(r.metrics.contributions||0)+(r.metrics.otherReceipts||0));
export function campaignMoneyCard(id){
  const candidate=campaignRoster.find(r=>r.id===id),units=unitsFor(id);
  if(!candidate&&!units.length)return '';
  const reports=units.flatMap(u=>u.reportIds.map(id=>reportById.get(id))),count=reports.reduce((n,r)=>n+r.rowCount,0);
  return '<section class="campaign-finance"><h3>Campaign money · 2026 cycle</h3><p>'+(reports.length?reports.length+' reports · '+count.toLocaleString()+' transaction and memo rows':'A complete filing ledger has not yet been matched to this candidate.')+'</p><button class="primary-button" data-campaign-money="'+escape(candidate?.id||units[0].candidateIds[0])+'">'+(reports.length?'Explore totals, donors & sources':'View filing coverage')+' →</button></section>';
}

export function mountCampaignMoney({openEntity}){
  const dialog=document.createElement('dialog');dialog.id='campaign-money';dialog.className='campaign-money-dialog';dialog.setAttribute('aria-labelledby','campaign-money-title');
  dialog.innerHTML='<form method="dialog"><button class="dialog-close" aria-label="Close campaign money">×</button></form><h2 id="campaign-money-title">Campaign money</h2><p class="finance-scope">Official candidate committee filings · 2026 election cycle · filings through '+catalog.asOf+'. Outside spending stays separate from candidate receipts.</p><div class="finance-selectors"><label>Candidate<select id="finance-candidate" aria-label="Candidate"><option value="">Choose a candidate…</option>'+campaignRoster.map(r=>'<option value="'+r.id+'">'+escape(r.name+' · '+r.party+' · '+r.office)+'</option>').join('')+'</select></label><label>Committee<select id="finance-unit" aria-label="Committee"></select></label><label>Report year<select id="finance-year" aria-label="Report year"><option value="">2025–2026</option><option>2026</option><option>2025</option></select></label></div><div id="finance-overview" aria-live="polite"></div><div id="finance-records" hidden><div class="finance-selectors"><label>Show<select id="finance-display" aria-label="Show"><option value="names">Totals by reported name</option><option value="rows">Individual transactions</option></select></label><label>Report<select id="finance-report" aria-label="Report"></select></label><label>Search names or records<input id="finance-search" type="search" placeholder="Donor, payee, employer or transaction…"></label><label>Money type<select id="finance-kind" aria-label="Money type"><option value="">All types</option>'+['contribution','loan','transfer-in','other-receipt','offset','spending','refund','loan-repayment','transfer-out','in-kind','loan-balance','debt-balance'].map(k=>'<option value="'+k+'">'+k.replaceAll('-',' ')+'</option>').join('')+'</select></label></div><div class="finance-row-tools"><label><input type="checkbox" id="finance-memos"> Include explanatory memo rows</label><button id="finance-csv" class="explore-button" disabled>Export matching rows (CSV)</button><a id="finance-csv-file" hidden>Save CSV ↧</a></div><p id="finance-row-status" role="status"></p><div class="finance-table-wrap"><table class="finance-transactions"><thead><tr><th>Date</th><th>Reported donor / payee</th><th>Type</th><th>Amount</th><th>Source record</th></tr></thead><tbody id="finance-rows"></tbody></table></div><nav class="finance-pagination" aria-label="Transaction pages"><button id="finance-previous" class="explore-button">Previous</button><span id="finance-page"></span><button id="finance-next" class="explore-button">Next</button></nav></div>';
  document.body.append(dialog);const $=id=>dialog.querySelector('#'+id);let active=null,loaded=[],filtered=[],page=0,request=0,nameView=true;const cache=new Map();
  function sourceLink(id,label){const s=sourceById.get(id);return s?'<a href="'+escape(s.url)+'" target="_blank" rel="noopener noreferrer">'+escape(label||s.publisher)+' ↗</a>':'';}
  function groupSource(report,category){
    if(!report.id.startsWith('oh-'))return report.sourceId;
    const id=['loan','loan-repayment','loan-balance'].includes(category)?'finance-oh-'+report.reportKey+'-31c':'finance-ohio-'+(['spending','refund','transfer-out'].includes(category)?'exp':'con')+'-'+report.year;
    return sourceById.has(id)?id:report.sourceId;
  }
  function candidateChanged(){const id=$('finance-candidate').value,units=unitsFor(id);$('finance-unit').innerHTML=units.map(u=>'<option value="'+u.id+'">'+escape(u.name)+'</option>').join('');renderUnit();}
  function renderUnit(){
    request++;loaded=[];active=null;$('finance-csv-file').hidden=true;const unit=unitById.get($('finance-unit').value),id=$('finance-candidate').value;
    if(!unit){$('finance-records').hidden=true;$('finance-overview').innerHTML='<p class="finance-coverage">'+(id?'No matched candidate committee ledger yet. This is missing coverage, not a zero-dollar campaign.':'Choose a candidate to explore their filing totals and sources.')+'</p><p>'+escape(catalog.scope)+'</p><p>'+escape(catalog.gaps.join(' '))+'</p><a href="https://www.fec.gov/data/" target="_blank" rel="noopener noreferrer">Federal filings ↗</a> · <a href="https://data.ohiosos.gov/portal/campaign-finance" target="_blank" rel="noopener noreferrer">Ohio filings ↗</a>';return;}
    const reports=unit.reportIds.map(id=>reportById.get(id)).filter(r=>!$('finance-year').value||r.year===Number($('finance-year').value)).sort((a,b)=>(a.period.end||a.filedAt||'').localeCompare(b.period.end||b.filedAt||'')||a.id.localeCompare(b.id));
    const totalReceipts=reports.some(r=>receipts(r)!==null)?reports.reduce((n,r)=>n+(receipts(r)||0),0):null;
    const fields=[['Reported receipts',totalReceipts],['Contributions within receipts',sum(reports,'contributions')],['Loans within receipts',sum(reports,'loans')],['Transfers within receipts',sum(reports,'transfers')],['Refunds & expense offsets within receipts',sum(reports,'offsets')],['Unitemized individual contributions · within receipts',sum(reports,'unitemizedIndividuals')],[unit.jurisdiction==='Federal filings'?'Other receipts':'Other receipts · includes loans',sum(reports,'otherReceipts')],['Reported disbursements',sum(reports,'disbursements')],['Contribution refunds within spending',sum(reports,'refunds')],['In-kind support · separate from cash',sum(reports,'inKind')]].filter(([label,v])=>v!==null||label==='Reported receipts');
    const blanks=reports.filter(r=>r.metrics.contributions===null||r.metrics.disbursements===null).length;
    $('finance-overview').innerHTML='<div class="finance-heading"><h3>'+escape(unit.name)+'</h3><button class="explore-button" data-finance-map="'+escape(id)+'">Explore candidate on map →</button></div><p>'+reports.length+' reports · '+reports.reduce((n,r)=>n+r.rowCount,0).toLocaleString()+' rows · '+escape(unit.jurisdiction)+(unit.designation?' · '+(unit.designation==='P'?'Principal campaign committee':'Other authorized committee')+' · '+escape(unit.id):'')+'</p>'+(reports.length?'':'<p class="finance-coverage">Committee identity is recorded, but no financial report was found in the retrieved listing. Fundraising remains unknown.</p>')+'<dl class="finance-totals">'+fields.map(([label,value])=>'<div><dt>'+escape(label)+'</dt><dd>'+escape(dollars(value))+'</dd></div>').join('')+'</dl><p class="finance-coverage">'+(blanks?blanks+' reports have blank summary fields; the totals show the amounts actually reported. ':'')+'Subcategories overlap the receipt or spending total. Transfers can also appear in another committee’s ledger; committee totals are not added across candidates. Cash balances and carried loans are not new donations. Federal totals follow the filing’s accounting basis and may include in-kind entries.</p><details class="finance-reports"><summary>Reports, reporting periods and sources</summary>'+reports.map(r=>'<article><h4>'+escape(r.title)+'</h4><p>'+(r.period.start?escape(r.period.start+' – '+r.period.end):'Activity dates are retained on each row; Ohio bulk covers do not state period boundaries.')+' · filed '+escape(r.filedAt||'date unavailable')+'</p><p>Reported receipts '+escape(dollars(receipts(r)))+' · spending '+escape(dollars(r.metrics.disbursements))+' · '+sourceLink(r.sourceId,'Original report data')+'</p>'+Object.entries(r.reconciliation).map(([key,v])=>'<p>'+escape(key)+': '+escape(dollars(v.itemizedCents))+' in itemized rows'+(v.differenceCents?'; '+escape(dollars(v.differenceCents))+' in the summary without matching named rows':v.differenceCents===0?'; reconciled':'; summary amount blank')+'</p>').join('')+(r.amendmentChain?.length>1?'<p>Current filing '+escape(r.reportKey)+' replaces earlier versions in this amendment chain.</p>':'')+'<p>'+escape(r.notes.join(' '))+'</p></article>').join('')+'</details>';
    const supplementary=(catalog.supplementaryDisclosures||[]).filter(r=>r.committeeId===unit.id);
    if(supplementary.length)$('finance-overview').insertAdjacentHTML('beforeend','<details class="finance-reports"><summary>Lobbyist bundling & contribution notices · '+supplementary.length+' filings</summary><p>These disclosures can describe amounts already included in the financial reports. They are retained as source context and are not added as new receipts.</p><ul>'+supplementary.map(r=>'<li><a href="'+escape(r.url)+'" target="_blank" rel="noopener noreferrer">'+escape((r.form.startsWith('F3L')?'Lobbyist bundling':'48-hour contribution notice')+' · filed '+r.filedAt+(r.start?' · '+r.start+' – '+r.end:''))+' ↗</a></li>').join('')+'</ul></details>');
    $('finance-records').hidden=!reports.length;$('finance-report').innerHTML=reports.slice().reverse().map(r=>'<option value="'+r.id+'">'+escape(r.title+' · '+r.rowCount.toLocaleString()+' rows')+'</option>').join('');if(reports.length)loadDisplay();
  }
  async function readCompressed(descriptor){
    let data=cache.get(descriptor.path);if(data)return data;
    const response=await fetch(new URL('./finance/2026/'+descriptor.path,import.meta.url));if(!response.ok)throw Error('The report could not be loaded.');
    const bytes=await response.arrayBuffer(),digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');
    if(digest!==descriptor.sha256)throw Error('The file differs from its published checksum.');
    data=JSON.parse(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text());cache.set(descriptor.path,data);if(cache.size>3)cache.delete(cache.keys().next().value);return data;
  }
  async function loadDisplay(){
    nameView=$('finance-display').value==='names';dialog.dataset.financeMode=nameView?'names':'rows';$('finance-search').placeholder=nameView?'Search reported donor or payee names…':'Donor, payee, employer or transaction…';const version=++request;page=0;loaded=[];filtered=[];$('finance-rows').innerHTML='';$('finance-csv').disabled=true;
    $('finance-report').disabled=nameView;$('finance-memos').closest('label').hidden=nameView;
    const unit=unitById.get($('finance-unit').value),report=reportById.get($('finance-report').value);active=report;
    $('finance-row-status').textContent=nameView?'Loading totals by reported name…':'Loading this report’s transactions…';
    dialog.querySelector('.finance-transactions thead').innerHTML=nameView?'<tr><th>Reported name</th><th>Money type</th><th>Total</th><th>Transactions</th><th>Report sources</th></tr>':'<tr><th>Date</th><th>Reported donor / payee</th><th>Type</th><th>Amount</th><th>Source record</th></tr>';
    try{
      if(nameView){const data=await readCompressed(unit.nameGroups);if(version!==request)return;const ids=new Set(unit.reportIds.filter(id=>!$('finance-year').value||reportById.get(id).year===Number($('finance-year').value)));loaded=groupReportedNames(data.rows,ids);}
      else{const data=await readCompressed(report);if(version!==request)return;if(data.reportId!==report.id||data.rows.length!==report.rowCount)throw Error('The report file is incomplete.');loaded=data.rows;}
      filterRows();
    }catch(error){if(version!==request)return;$('finance-row-status').textContent=error.message+' Select the view again to retry.';}
  }
  function filterRows(){
    page=0;$('finance-csv-file').hidden=true;const q=$('finance-search').value.toLocaleLowerCase(),kind=$('finance-kind').value;
    filtered=loaded.filter(r=>nameView?(!kind||r.category===kind)&&(!q||r.name.toLocaleLowerCase().includes(q)):(!r[5]||$('finance-memos').checked)&&(!kind||r[2]===kind)&&(!q||[r[0],r[3],r[7],r[8],r[9]].join(' ').toLocaleLowerCase().includes(q)));renderRows();
  }
  function renderRows(){
    const start=page*75,rows=filtered.slice(start,start+75);
    $('finance-row-status').textContent=nameView?filtered.length.toLocaleString()+' groups of reported names. Identical names are grouped as written; they do not establish a unique person. Memo rows and carried balances are excluded.':filtered.length.toLocaleString()+' matching rows · '+active.title+'. Memo and balance rows do not add to cash totals.';
    $('finance-rows').innerHTML=nameView?rows.map((r,index)=>'<tr><td><strong>'+escape(r.name)+'</strong></td><td>'+escape(r.category.replaceAll('-',' '))+'</td><td>'+escape(dollars(r.amountCents))+'</td><td>'+r.count.toLocaleString()+'</td><td><details><summary>'+r.reportIds.length+' reports · see rows</summary>'+r.reportIds.map(id=>{const report=reportById.get(id);return '<button class="small-link" data-finance-group="'+(start+index)+'" data-finance-report="'+id+'">'+escape(report.title)+' · rows →</button> '+sourceLink(groupSource(report,r.category),'Source');}).join('<br>')+'</details></td></tr>').join(''):rows.map(r=>'<tr'+(r[5]?' class="finance-memo"':'')+'><td>'+escape(r[1]||'Not stated')+'</td><td><strong>'+escape(r[3])+'</strong>'+(r[7]||r[8]?'<small>'+escape([r[7],r[8]].filter(Boolean).join(' · '))+'</small>':'')+(r[9]?'<small>'+escape(r[9])+'</small>':'')+'</td><td>'+escape(r[2].replaceAll('-',' '))+(r[5]?' · memo':'')+'</td><td>'+escape(dollars(r[4]))+'</td><td>'+sourceLink(sourceById.has(r[11].split(':')[0])?r[11].split(':')[0]:active.sourceId,r[6])+'<small>'+escape(r[11])+'</small><code>'+escape(r[0])+'</code></td></tr>').join('');
    $('finance-page').textContent=filtered.length?(start+1)+'–'+Math.min(start+75,filtered.length)+' of '+filtered.length.toLocaleString():'No matching rows';$('finance-previous').disabled=page===0;$('finance-next').disabled=start+75>=filtered.length;$('finance-csv').disabled=!filtered.length;
  }
  $('finance-candidate').addEventListener('change',candidateChanged);$('finance-unit').addEventListener('change',renderUnit);$('finance-year').addEventListener('change',renderUnit);$('finance-report').addEventListener('change',loadDisplay);$('finance-display').addEventListener('change',loadDisplay);for(const id of ['finance-search','finance-kind','finance-memos'])$(id).addEventListener(id==='finance-search'?'input':'change',filterRows);
  $('finance-previous').addEventListener('click',()=>{page--;renderRows()});$('finance-next').addEventListener('click',()=>{page++;renderRows()});
  $('finance-csv').addEventListener('click',()=>{
    const source=sourceById.get(active.sourceId),headers=nameView?['reportedName','category','amountCents','transactionCount','reportIds','sourceURLs']:catalog.columns.concat(['sourceURL']);
    const rows=nameView?filtered.map(r=>[r.name,r.category,r.amountCents,r.count,r.reportIds.join(';'),r.reportIds.map(id=>sourceById.get(groupSource(reportById.get(id),r.category)).url).join(';')]):filtered.map(r=>r.concat([sourceById.get(r[11].split(':')[0])?.url||source.url]));
    const url=URL.createObjectURL(new Blob([financeCSV(headers,rows)],{type:'text/csv;charset=utf-8'}));const a=$('finance-csv-file');if(a.href.startsWith('blob:'))URL.revokeObjectURL(a.href);a.href=url;a.download=(nameView?$('finance-unit').value+'-reported-names':active.id+'-rows')+'.csv';a.hidden=false;if(window.parent!==window)window.parent.postMessage({channel:'columbus-explorer',type:'download-campaign-money',text:financeCSV(headers,rows),name:a.download},location.origin);else a.click();
  });
  dialog.addEventListener('click',event=>{const button=event.target.closest('[data-finance-group]');if(!button)return;const group=filtered[Number(button.dataset.financeGroup)];$('finance-display').value='rows';$('finance-report').value=button.dataset.financeReport;$('finance-search').value=group.name;loadDisplay();});
  document.addEventListener('click',event=>{const opener=event.target.closest('[data-campaign-money]');if(opener){$('finance-candidate').value=opener.dataset.campaignMoney||'';candidateChanged();dialog.showModal();}const map=event.target.closest('[data-finance-map]');if(map){dialog.close();openEntity(map.dataset.financeMap);}});
  candidateChanged();return {open(id=''){$('finance-candidate').value=id;candidateChanged();dialog.showModal();}};
}
